const R2_WORKER='https://flat-lab-b020subir-imagenes.ronaldochoacastro.workers.dev';
const ST={d:null,ld:false,err:''};
const stFmt=b=>b<1024?b+' B':b<1048576?(b/1024).toFixed(1).replace('.',',')+' KB':b<1073741824?(b/1048576).toFixed(1).replace('.',',')+' MB':(b/1073741824).toFixed(2).replace('.',',')+' GB';
async function stLoad(){if(ST.ld)return;ST.ld=true;ST.err='';if(at==='alm')render(true);try{const t=await QH.token();if(!t)throw new Error('tok');const r=await fetch(R2_WORKER+'/stats',{headers:{Authorization:'Bearer '+t}});if(r.status===401||r.status===403)throw new Error('perm');if(!r.ok)throw new Error('old');ST.d=await r.json()}catch(e){ST.err=e&&e.message==='perm'?'No tienes permiso: entra con tu cuenta de administrador.':e&&e.message==='old'?'El Worker aún no tiene la función de estadísticas. Actualiza el código del Worker (worker_v2.js).':'No se pudo consultar el almacenamiento. Revisa tu conexión e inténtalo de nuevo.'}ST.ld=false;if(at==='alm')render(true)}
async function r2up(du){try{/* v212: antes solo subia a R2 el administrador. El Worker acepta a cualquier cuenta con correo (no anonima); si no, la foto queda como antes, dentro del documento */const t=await QH.token();if(!t)return du;try{const pl=JSON.parse(atob(t.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(!pl.email||(pl.firebase&&pl.firebase.sign_in_provider==='anonymous'))return du}catch(_){return du}const b=await(await fetch(du)).blob();const r=await fetch(R2_WORKER,{method:'POST',headers:{Authorization:'Bearer '+t,'Content-Type':b.type==='image/webp'?'image/webp':'image/jpeg'},body:b});if(!r.ok)return du;const j=await r.json();return j.url||du}catch(e){return du}}
/* v201: borrar de R2 las imágenes que dejan de usarse. r2q encola las URL de un documento viejo; r2gc borra solo las que ya no aparecen en ningún documento vivo */
const R2Q=new Set(),R2RE=/https:\/\/pub-419ea53b95de40199910716cc66fd035\.r2\.dev\/u\/[A-Za-z0-9]+\/\d+-[a-f0-9]{8}\.(?:jpg|webp)/g;
function r2q(o){if(MODE!=='admin'||!o)return;try{(JSON.stringify(o).match(R2RE)||[]).forEach(u=>R2Q.add(u))}catch(e){}}
async function r2gc(live){if(MODE!=='admin'||!R2Q.size)return;try{const L=JSON.stringify(live);[...R2Q].forEach(u=>{if(L.includes(u))R2Q.delete(u)});const dead=[...R2Q];if(!dead.length)return;const t=await QH.token();if(!t)return;for(let i=0;i<dead.length;i+=50){const c=dead.slice(i,i+50),r=await fetch(R2_WORKER,{method:'DELETE',headers:{Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({urls:c})});if(r.ok)c.forEach(u=>R2Q.delete(u))}}catch(e){}}
/* v202: limpieza de huérfanas. Lista lo que subió este usuario a R2 y lo compara con lo que usa Firestore; solo toca archivos de más de un día */
const OR={ld:false,res:null,msg:''};
async function r2sweep(){const t=await QH.token();if(!t)throw new Error('tok');const live=await QH.r2live(),all=[];let cur='';do{const r=await fetch(R2_WORKER+'/list'+(cur?'?cursor='+encodeURIComponent(cur):''),{headers:{Authorization:'Bearer '+t}});if(!r.ok)throw new Error(r.status===401||r.status===403?'perm':'old');const j=await r.json();(j.objects||[]).forEach(o=>all.push({u:j.base+o.key,s:o.size,k:o.key}));cur=j.cursor||''}while(cur);if(all.length&&!live.size)throw new Error('empty');const lim=Date.now()-864e5,list=all.filter(o=>!live.has(o.u)&&(parseInt(o.k.split('/')[2])||Date.now())<lim);return{list,total:all.length,bytes:list.reduce((a,o)=>a+o.s,0)}}
const orphErr=e=>{const m=e&&e.message;return m==='perm'?'No tienes permiso: entra con tu cuenta de administrador.':m==='old'?'El Worker aún no tiene la función de listar. Publica worker_v5.js.':m==='empty'?'No se pudo leer lo que usan las publicaciones; por seguridad no se borró nada.':'No se pudo revisar. Revisa tu conexión e inténtalo de nuevo.'};
async function orphScan(){if(OR.ld)return;OR.ld=true;OR.msg='';OR.res=null;if(at==='alm')render(true);try{const r=await r2sweep();OR.res={n:r.list.length,bytes:r.bytes};OR.msg=r.list.length?'Se encontraron '+r.list.length.toLocaleString('es-CO')+' imágenes huérfanas ('+stFmt(r.bytes)+') de '+r.total.toLocaleString('es-CO')+' tuyas.':'No hay imágenes huérfanas.'}catch(e){OR.msg=orphErr(e)}OR.ld=false;if(at==='alm')render(true)}
async function orphGo(){if(OR.ld||!OR.res)return;if(!await askC('¿Eliminar '+OR.res.n.toLocaleString('es-CO')+' imágenes que ya no usa ninguna publicación? No se puede deshacer.'))return;OR.ld=true;OR.msg='';if(at==='alm')render(true);try{const r=await r2sweep(),t=await QH.token();let n=0;for(let i=0;i<r.list.length;i+=50){const c=r.list.slice(i,i+50),x=await fetch(R2_WORKER,{method:'DELETE',headers:{Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({urls:c.map(o=>o.u)})});if(!x.ok)throw new Error('del');n+=((await x.json()).deleted||[]).length}OR.msg='Se eliminaron '+n.toLocaleString('es-CO')+' imágenes.';OR.res=null;ST.d=null;ST.ld=false;stLoad()}catch(e){OR.msg=e&&e.message==='del'?'Se interrumpió el borrado. Vuelve a buscar y a intentarlo.':orphErr(e)}OR.ld=false;if(at==='alm')render(true)}
/* v200: ajustar la imagen al recuadro con el tamaño final antes de subirla. Devuelve un Blob recortado, null si cancelan, o el archivo original si no se puede abrir */
function cropImg(file,ratio,title,maxOut){return new Promise(res=>{
if(!file||!/^image\/(jpe?g|png|webp)$/i.test(file.type||'')){res(file);return}
const url=URL.createObjectURL(file),im=new Image();
im.onerror=()=>{URL.revokeObjectURL(url);res(file)};
im.onload=()=>{
const iw=im.naturalWidth,ih=im.naturalHeight;if(!iw||!ih){URL.revokeObjectURL(url);res(file);return}
const maxW=Math.min(innerWidth-56,440),maxH=innerHeight*.45,fw=Math.round(Math.min(maxW,maxH*ratio)),fh=Math.round(fw/ratio),s0=Math.max(fw/iw,fh/ih);
const o=document.createElement('div');o.id='crp';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label',title);
o.style.cssText='position:fixed;inset:0;z-index:100000;background:#0b1a3aee;display:grid;place-items:center;padding:12px;overflow:auto';
o.innerHTML='<div style="background:#fff;color:#111827;border-radius:18px;padding:16px;width:'+(fw+32)+'px;max-width:100%;box-sizing:border-box;display:flex;flex-direction:column;gap:10px"><h2 style="margin:0;font-size:18px">'+esc(title)+'</h2><p style="margin:0;font-size:14px">Arrastra la imagen para moverla y usa el control para acercarla o alejarla. Lo que ves dentro del recuadro es lo que se mostrará en la página.</p><div id="crp-f" tabindex="0" aria-label="Recuadro de ajuste. Flechas para mover, más y menos para acercar" style="position:relative;width:'+fw+'px;height:'+fh+'px;overflow:hidden;border-radius:14px;background:#fff;touch-action:none;cursor:grab;margin:0 auto;outline:1px solid #d1d5db"></div><label style="display:flex;align-items:center;gap:8px;font-size:14px">Zoom <input id="crp-z" type="range" min="1" max="4" step="0.01" value="1" style="flex:1" aria-label="Acercar o alejar"></label><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="btn pink" id="crp-ok">Usar esta imagen</button><button type="button" class="btn ghost" id="crp-no">Cancelar</button></div></div>';
const f=o.querySelector('#crp-f'),zr=o.querySelector('#crp-z');
im.alt='';im.draggable=false;im.style.cssText='position:absolute;max-width:none;max-height:none;user-select:none;-webkit-user-drag:none;pointer-events:none';f.appendChild(im);
const zm=Math.min(1,Math.min(fw/iw,fh/ih)/s0);let z=zm,ox=(fw-iw*s0*zm)/2,oy=(fh-ih*s0*zm)/2;zr.min=zm;zr.value=z;
const sc=()=>s0*z,clamp=()=>{const s=sc();ox=iw*s<=fw?(fw-iw*s)/2:Math.min(0,Math.max(fw-iw*s,ox));oy=ih*s<=fh?(fh-ih*s)/2:Math.min(0,Math.max(fh-ih*s,oy))},
draw=()=>{const s=sc();im.style.width=iw*s+'px';im.style.height=ih*s+'px';im.style.left=ox+'px';im.style.top=oy+'px'},
setZ=(nz,px,py)=>{nz=Math.min(4,Math.max(zm,nz));const s=sc(),cx=(px-ox)/s,cy=(py-oy)/s;z=nz;const n=sc();ox=px-cx*n;oy=py-cy*n;clamp();zr.value=z;draw()};
clamp();draw();
const ps=new Map(),dist=()=>{const a=[...ps.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)};let pd=0;
f.addEventListener('pointerdown',e=>{f.setPointerCapture(e.pointerId);ps.set(e.pointerId,{x:e.clientX,y:e.clientY});pd=ps.size===2?dist():0;f.style.cursor='grabbing'});
f.addEventListener('pointermove',e=>{const p=ps.get(e.pointerId);if(!p)return;if(ps.size===1){ox+=e.clientX-p.x;oy+=e.clientY-p.y;clamp();draw()}p.x=e.clientX;p.y=e.clientY;if(ps.size===2){const d=dist();if(pd)setZ(z*d/pd,fw/2,fh/2);pd=d}});
const up=e=>{ps.delete(e.pointerId);pd=ps.size===2?dist():0;if(!ps.size)f.style.cursor='grab'};
f.addEventListener('pointerup',up);f.addEventListener('pointercancel',up);
f.addEventListener('wheel',e=>{e.preventDefault();const r=f.getBoundingClientRect();setZ(z*(e.deltaY<0?1.08:1/1.08),e.clientX-r.left,e.clientY-r.top)},{passive:false});
zr.oninput=()=>setZ(+zr.value,fw/2,fh/2);
f.addEventListener('keydown',e=>{const k=e.key,d=12;if(k==='ArrowLeft')ox+=d;else if(k==='ArrowRight')ox-=d;else if(k==='ArrowUp')oy+=d;else if(k==='ArrowDown')oy-=d;else if(k==='+'||k==='=')return setZ(z*1.1,fw/2,fh/2);else if(k==='-')return setZ(z/1.1,fw/2,fh/2);else return;e.preventDefault();clamp();draw()});
const kd=e=>{if(e.key==='Escape'){e.stopPropagation();done(null)}};
const done=v=>{document.removeEventListener('keydown',kd,true);o.remove();URL.revokeObjectURL(url);res(v)};
document.addEventListener('keydown',kd,true);
o.querySelector('#crp-no').onclick=()=>done(null);
o.querySelector('#crp-ok').onclick=()=>{const s=sc(),dx=Math.max(0,ox),dy=Math.max(0,oy),dw=Math.min(fw,ox+iw*s)-dx,dh=Math.min(fh,oy+ih*s)-dy,ow=Math.max(1,Math.round(Math.min(maxOut||1200,fw/s))),oh=Math.max(1,Math.round(ow/ratio)),k=ow/fw,c=document.createElement('canvas'),g=c.getContext('2d');c.width=ow;c.height=oh;g.fillStyle='#fff';g.fillRect(0,0,ow,oh);g.drawImage(im,(dx-ox)/s,(dy-oy)/s,dw/s,dh/s,dx*k,dy*k,dw*k,dh*k);c.toBlob(b=>{if(b&&b.type==='image/webp')return done(b);c.toBlob(b2=>done(b2||file),'image/png')},'image/webp',.95)};
document.body.appendChild(o);o.querySelector('#crp-ok').focus()};
im.src=url})}
function resize(file,max=360,q=.7,local){/* v213: local=1 no sube a R2 (foto de perfil: se guarda solo en este dispositivo) */return new Promise(res=>{const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);(local?(x=>Promise.resolve(x)):r2up)((w=>w.slice(0,15)==='data:image/webp'?w:c.toDataURL('image/jpeg',q))(c.toDataURL('image/webp',q))).then(res)};i.onerror=()=>res('');i.src=r.result};r.onerror=()=>res('');r.readAsDataURL(file)})}

function cartHTML(){const groups={};Object.entries(S.cart).forEach(([k,q])=>{const[sid,pid]=k.split('|'),s=S.stores.find(x=>x.id===sid),p=s&&s.products.find(x=>x.id===pid);if(p)(groups[sid]=groups[sid]||{s,items:[]}).items.push({p,q,k})});
const gs=Object.values(groups);let h=`<div class="row" style="justify-content:space-between;align-items:center"><h2>Tu carrito</h2><button class="btn ghost" data-act="closeCart">Cerrar</button></div>`;
if(!gs.length)return h+`<div class="empty">Tu carrito está vacío.</div>`;
return h+gs.map(g=>{const t=g.items.reduce((a,i)=>a+i.p.price*i.q,0);return `<div class="cg"><h3>${esc(g.s.name)}</h3>${g.items.map(i=>`<div class="ci"><span>${esc(i.p.name)}${vTx(i.k)?`<br><small>${esc(vTx(i.k))}</small>`:''}<br><small>${money(i.p.price)}</small></span><span class="qty"><button data-act="dec" data-k="${i.k}" aria-label="Quitar uno">−</button> ${i.q} <button data-act="inc" data-k="${i.k}" aria-label="Agregar uno">+</button></span></div>`).join('')}<div class="ci"><b>Total</b><b>${money(t)}</b></div>${typeof ordFoot==='function'?ordFoot(g.s,t)/* v320 */:`<button class="btn pink" style="width:100%" data-act="order" data-id="${g.s.id}">Pedir por WhatsApp</button>`}</div>`}).join('')}
function openCart(){$('#drawer').innerHTML=cartHTML();$('#drawer').classList.add('open')}
const refreshCart=()=>{$('#cc').textContent=Object.values(S.cart).reduce((a,b)=>a+b,0);$('#drawer').innerHTML=cartHTML();save()};

